diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..71f2204
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,78 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, NOW } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+function withAnnexStock() {
+  const ctx = app();
+  const { store } = ctx;
+  store.data.batches.push({ id: 10, itemId: 1, lot: "AN-1", qty: 3, receivedOn: "2026-10-27", expires: "2026-10-30", location: "annex-fridge" });
+  store.data.seq.batch = 10;
+  return ctx;
+}
+
+test("the seed has the annex site and fridge", () => {
+  const { store } = app();
+  assert.deepEqual(store.data.sites.map((s) => s.id), ["main", "annex"]);
+  const loc = store.data.locations.find((l) => l.id === "annex-fridge");
+  assert.equal(loc.site, "annex");
+  assert.equal(loc.tempC, 4);
+});
+
+test("no header means main; an unknown site is a 400", async () => {
+  const { handle } = withAnnexStock();
+  assert.equal((await handle({ path: "/items" })).body.find((i) => i.id === 1).onHand, 10);
+  const bad = await handle({ path: "/items", headers: { "x-larder-site": "nope" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /nope/);
+});
+
+test("batches and stock on hand only show the request's site", async () => {
+  const { handle } = withAnnexStock();
+  const batches = await handle({ path: "/batches", headers: annex });
+  assert.deepEqual(batches.body.map((b) => b.id), [10]);
+  assert.equal((await handle({ path: "/items", headers: annex })).body.find((i) => i.id === 1).onHand, 3);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/batches/10" })).status, 404);
+  const w = await handle({ method: "POST", path: "/batches/1/waste", headers: annex, body: { qty: 1 } });
+  assert.equal(w.status, 404);
+});
+
+test("cooking only uses the site's stock", async () => {
+  const { handle, store } = withAnnexStock();
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 3);
+});
+
+test("alerts and stock value only see the site", async () => {
+  const { handle } = withAnnexStock();
+  const alerts = await handle({ path: "/alerts", headers: annex });
+  assert.deepEqual(alerts.body.expiring.map((b) => b.id), [10]);
+  assert.equal(alerts.body.lowStock.find((l) => l.itemId === 1).qty, 3);
+  const value = await handle({ path: "/reports/stock-value", headers: annex });
+  assert.equal(value.body.totalCents, 3 * 180);
+});
+
+test("stock-takes stay within the site", async () => {
+  const { handle } = withAnnexStock();
+  const other = await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } });
+  assert.equal(other.body.error.code, "unknown_location");
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } });
+  assert.equal(take.status, 201);
+  const count = await handle({ method: "POST", path: `/stocktakes/${take.body.id}/counts`, headers: annex, body: { batchId: 10, counted: 2 } });
+  assert.equal(count.status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.body.id}/finish` })).status, 404);
+  const done = await handle({ method: "POST", path: `/stocktakes/${take.body.id}/finish`, headers: annex });
+  assert.equal(done.body.lines[0].diff, -1);
+});
+
+test("receiving into another site's location is refused", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/orders/3/send" });
+  const res = await handle({ method: "POST", path: "/orders/3/receive", headers: annex, body: { lots: [{ lot: "X", expires: null, location: "dry" }] } });
+  assert.equal(res.body.error.code, "unknown_location");
+  assert.ok(NOW);
+});
